def js_artifact(language:str, slug:str)->tuple[str,str,str]:
    body, assertion=JS[slug]
    name={"canonical-path":"canonicalPath","inherited-policy":"resolvePolicy","dependency-ready":"dependencyReady","ttl-cache":"liveCache","budget-batches":"budgetBatches","backpressure-actions":"backpressureActions","schedule-slots":"scheduleSlots","fixed-point-allocation":"allocateFixed","change-order":"orderChanges","clamped-slice":"clampedSlice"}[slug]
    if language=="javascript":
        ref=body+f"exports.{name}=f;\n"; test=f"const{{{name}:f}}=require('./solution');if(!({assertion}))throw Error('contract');\n"
        bad=f"exports.{name}=()=>null;\n"
    else:
        fn_type={
            "canonical-path":"(base:string,segments:string[])=>string|null","inherited-policy":"(path:string,key:string,rules:Record<string,Record<string,string>>)=>string|null",
            "dependency-ready":"(items:string[][],completed:string[])=>string[]|null","ttl-cache":"(entries:string[][],now:number)=>string[]|null",
            "budget-batches":"(weights:number[],budget:number)=>number[]|null","backpressure-actions":"(samples:number[][])=>string[]|null",
            "schedule-slots":"(start:number,end:number,duration:number,busy:number[][])=>number[]|null","fixed-point-allocation":"(total:number,weights:number[])=>number[]|null",
            "change-order":"(changes:string[][])=>string[]|null","clamped-slice":"(text:string,start:number,end:number)=>string",
        }[slug]
        ref=body.replace("const f=",f"const f:{fn_type}=",1)
        replacements={
            "canonical-path":(("const p=[]","const p:string[]=[]"),),
            "dependency-ready":(("new Map,k=","new Map<string,string[]>(),k="),("const cyc=(n,s)=>","const cyc=(n:string,s:Set<string>):boolean=>"),("new Set([...s,n])","new Set<string>([...s,n])")),
            "ttl-cache":(("const s=new Set,o=[]","const s=new Set<string>(),o:string[]=[]"),),
            "budget-batches":(("const o=[]","const o:number[]=[]"),),
            "backpressure-actions":(("const o=[]","const o:string[]=[]"),),
            "schedule-slots":(("const ok=x=>","const ok=(x:number):boolean=>"),("),m=[]", "),m:number[][]=[]"),("const o=[]","const o:number[]=[]")),
            "fixed-point-allocation":(("const q=w.map", "const q:number[][]=w.map"),),
            "change-order":(("new Map,k=","new Map<string,[string,number]>(),k="),("const o=[],z=new Set","const o:string[]=[],z=new Set<string>")),
        }.get(slug,())
        for old,new in replacements:ref=ref.replace(old,new)
        if slug=="dependency-ready":ref=ref.replace("d.get(n).some", "d.get(n)!.some")
        if slug=="schedule-slots":ref=ref.replace("m.at(-1)[1]", "m.at(-1)![1]")
        ref+=f"export{{f as {name}}};\n"
        test=f"import{{{name} as f}}from'./solution';if(!({assertion}))throw Error('contract');\n";bad=f"export const {name}=(..._x:any[]):any=>null;\n"
    return ref,bad,test

